/**
 * Optional interface sounds made with the Web Audio API (no audio files, nothing generated by AI tools).
 * Silent unless the player has turned sound on, and only ever started by a player gesture.
 * Every sound has a visual equivalent, so nothing is lost when muted.
 */
type Tone = 'select' | 'confirm' | 'good' | 'caution';

const tones: Record<Tone, { frequency: number; to: number; duration: number }> = {
  select: { frequency: 520, to: 560, duration: 0.07 },
  confirm: { frequency: 392, to: 523, duration: 0.16 },
  good: { frequency: 523, to: 784, duration: 0.28 },
  caution: { frequency: 330, to: 262, duration: 0.3 },
};

let context: AudioContext | null = null;

export function playTone(tone: Tone, muted: boolean): boolean {
  if (muted || typeof window.AudioContext === 'undefined') return false;
  try {
    context ??= new window.AudioContext();
    const { frequency, to, duration } = tones[tone];
    const start = context.currentTime;
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(frequency, start);
    oscillator.frequency.linearRampToValueAtTime(to, start + duration);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.linearRampToValueAtTime(0.08, start + 0.02);
    gain.gain.linearRampToValueAtTime(0.0001, start + duration);
    oscillator.connect(gain).connect(context.destination);
    oscillator.start(start);
    oscillator.stop(start + duration + 0.02);
    document.documentElement.dataset.lastTone = tone;
    return true;
  } catch {
    return false;
  }
}
